function translateText(value){
  const text=String(value),trimmed=text.trim();
  if(state.language!=='zh-Hant'||!trimmed)return text;
  let translated=ZH_HANT[trimmed];
  if(translated===undefined){
    const rules=[
      [/^(\d+) correct so far$/,(_,n)=>`目前答對 ${n} 題`],
      [/^(\d+) \/ (\d+) · (\d+) correct$/,(_,i,n,c)=>`${i} / ${n} · 答對 ${c} 題`],
      [/^(\d+) \/ (\d+) units$/,(_,i,n)=>`${i} / ${n} 張字卡`],
      [/^(\d+(?:\.\d+)?) \/ 1 mark$/,(_,n)=>`${n} / 1 分`],
      [/^(\d+) items are ready for another look\.$/,(_,n)=>`有 ${n} 題可再次練習。`],
      [/^(\d+) vocabulary forms · (\d+) secure$/,(_,n,k)=>`${n} 個詞彙 · 已記熟 ${k} 個`],
      [/^(\d+) forms · a polite or bracketed alternative gets its own entry$/,(_,n)=>`${n} 種形式 · 禮貌或括號內變體各自列出`],
      [/^(\d+) vocabulary forms include polite and optional forms, expressions and related words from PDF pp\.1 & 6\. Learning aids are separate from the timed mock\.$/,(_,n)=>`${n} 種詞彙形式包含 PDF 第 1、6 頁的禮貌與可選形式、表達方式及相關詞彙。計時模擬測驗不提供學習提示。`],
      [/^(\d+) (forms|vocabulary forms|WORDS)$/,(_,n)=>`${n} 個詞彙`],
      [/^(\d+) groups$/,(_,n)=>`${n} 個分類`],
      [/^(\d+) scenes$/,(_,n)=>`${n} 個情境`],
      [/^(\d+) sentences$/,(_,n)=>`${n} 句`],
      [/^(\d+) secure · two correct answers in a row$/,(_,n)=>`${n} 個已記熟 · 連續答對兩次`],
      [/^(\d+) WORDS · QUIZ VOCABULARY$/,(_,n)=>`${n} 個詞彙 · 測驗範圍`],
      [/^(\d+) WORDS · VISUAL PRACTICE$/,(_,n)=>`${n} 個詞彙 · 圖解練習`],
      [/^(\d+) SCENES · QUIZ EXPRESSIONS$/,(_,n)=>`${n} 個情境 · 測驗表達方式`],
      [/^ROUND (\d+) \/ (\d+)$/,(_,i,n)=>`本回合 ${i} / ${n}`],
      [/^CHAPTER (\d+) · SENTENCE REBUILD$/,(_,n)=>`第 ${n} 課 · 句子重組`],
      [/^CH\.(\d+) · (\d+) PUZZLES$/,(_,ch,n)=>`第 ${ch} 課 · ${n} 題`],
      [/^CH\.(\d+) · P\.(\d+)$/,(_,ch,p)=>`第 ${ch} 課 · 第 ${p} 頁`],
      [/^Ch\. ?(\d+) · PDF p\.(\d+)(?: · (.*))?$/,(_,ch,p,group)=>`第 ${ch} 課 · PDF 第 ${p} 頁${group?' · '+(ZH_HANT[group]||group):''}`],
      [/^Ch\.(\d+) · (.*)$/,(_,ch,title)=>`第 ${ch} 課 · ${ZH_HANT[title]||title}`],
      [/^(Vocabulary|Sentences) · (\d+\/\d+)$/,(_,section,n)=>`${ZH_HANT[section]} · ${n}`],
      [/^QUESTION (\d+) · 2 MARKS$/,(_,n)=>`第 ${n} 題 · 2 分`],
      [/^You have (\d+) unfinished vocabulary questions and (\d+) unfinished sentences\. Submit now for your score, or keep working\.$/,(_,a,b)=>`尚有 ${a} 題詞彙及 ${b} 題句子未完成。你可以立即提交評分，或繼續作答。`],
      [/^The correct match is (.+)\.$/,(_,answer)=>`正確配對是 ${answer}。`],
      [/^Remember this pairing: (.+)\.$/,(_,answer)=>`請記熟這組配對：${answer}。`],
      [/^(.+) The speaker is labelled You, and the other person Listener\.$/,(_,scene)=>`${ZH_HANT[scene]||scene}圖中標示「你 · 說話者」與「聽話者」。`],
      [/^(\d+\. )(.+)$/,(_,num,prompt)=>ZH_HANT[prompt]?num+ZH_HANT[prompt]:trimmed],
      [/^Return (.+) to word bank$/,(_,tile)=>`將 ${tile} 移回選項區`],
      [/^Listen to (.+)$/,(_,word)=>`聆聽 ${word}`],
      [/^Words beginning with (.+)$/,(_,kana)=>`以 ${kana} 開首的詞彙`],
      [/^(.+), (\d+) vocabulary forms(?:, (\d+) secure)?$/,(_,kana,n,k)=>`${kana}，${n} 個詞彙${k?`，已記熟 ${k} 個`:''}`]
    ];
    for(const [pattern,replace] of rules){if(pattern.test(trimmed)){translated=trimmed.replace(pattern,replace);break;}}
  }
  return translated===undefined?text:text.replace(trimmed,()=>translated);
}
function localizeMarkup(html){
  if(state.language!=='zh-Hant')return html;
  const encode=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const decode=s=>s.replace(/&(?:amp|lt|gt|quot|#39);/g,e=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'"}[e]));
  const translate=s=>{const decoded=decode(s),translated=translateText(decoded);return translated===decoded?s:encode(translated);};
  // Translate rendered text and accessible labels, never URLs, values or event attributes.
  return html.replace(/<[^>]*>|[^<]+/g,part=>part.startsWith('<')?part.replace(/\b(aria-label|placeholder)="([^"]*)"/g,(_,key,value)=>`${key}="${translate(value)}"`):translate(part));
}
